```go
package bookstore

import "sort"

var groupPrices = [6]int{0, 800, 1520, 2160, 2560, 3000}

func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}
	sort.Sort(sort.Reverse(sort.IntSlice(counts[:5])))
	return solve(counts[:5], map[[5]int]int{})
}

func solve(counts []int, memo map[[5]int]int) int {
	key := [5]int(counts)
	if v, ok := memo[key]; ok {
		return v
	}
	// count how many titles still have copies
	n := 0
	for i := 0; i < 5 && counts[i] > 0; i++ {
		n++
	}
	if n == 0 {
		memo[key] = 0
		return 0
	}
	best := -1
	for k := 1; k <= n; k++ {
		next := make([]int, 5)
		copy(next, counts)
		for i := 0; i < k; i++ {
			next[i]--
		}
		sort.Sort(sort.Reverse(sort.IntSlice(next)))
		c := groupPrices[k] + solve(next, memo)
		if best == -1 || c < best {
			best = c
		}
	}
	memo[key] = best
	return best
}
```

