package bookstore

import "sort"

// groupPrices[k] is the total price of a group of k distinct books, where a
// single book costs $8 (800 cents) and the discount depends on the group size:
//
//	1 book:  0% off -> 800
//	2 books:  5% off -> 1520
//	3 books: 10% off -> 2160
//	4 books: 20% off -> 2560
//	5 books: 25% off -> 3000
var groupPrices = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket of
// books. Each book is identified by an integer 1-5 (the five titles in the
// series). Books are grouped into sets of distinct titles to maximize the
// discount.
func Cost(books []int) int {
	var counts [5]int
	for _, book := range books {
		counts[book-1]++
	}
	// Keep the counts sorted in descending order so that states are canonical
	// and can be memoized.
	sort.Sort(sort.Reverse(sort.IntSlice(counts[:5])))
	return solve(counts, map[[5]int]int{})
}

// solve returns the minimum cost to buy the books described by the
// descending-sorted per-title counts, memoizing over previously seen states.
//
// At each step we form one group from the k titles that currently have the
// most copies remaining (for some k between 1 and the number of titles that
// still have copies). Considering every possible k and taking the minimum
// finds the optimal grouping, including cases where a smaller group now leads
// to a cheaper overall result (e.g. two groups of four beats a group of five
// plus a group of three).
func solve(counts [5]int, memo map[[5]int]int) int {
	if v, ok := memo[counts]; ok {
		return v
	}

	// n is the number of titles that still have at least one copy.
	n := 0
	for i := 0; i < 5 && counts[i] > 0; i++ {
		n++
	}
	if n == 0 {
		memo[counts] = 0
		return 0
	}

	best := -1
	for k := 1; k <= n; k++ {
		next := counts
		for i := 0; i < k; i++ {
			next[i]--
		}
		sort.Sort(sort.Reverse(sort.IntSlice(next[:5])))
		cost := groupPrices[k] + solve(next, memo)
		if best == -1 || cost < best {
			best = cost
		}
	}

	memo[counts] = best
	return best
}
